  "figureType": "diagram",
  "elements": [
    "Vertical 'Energy' axis arrow on the left, gradient from pale yellow to orange",
    "Horizontal 'Reaction progress' axis at the bottom with a magenta arrow tip",
    "Pale blue rectangular background panel",
    "Reactants: Benzene ring + Br2 (magenta)",
    "Dashed horizontal reference line for reactants energy level",
    "First transition state peak with a dashed horizontal line",
    "Intermediate: Arenium ion structure (partially unsaturated ring, H and magenta Br on same carbon, plus charge)",
    "Black curve showing the common reaction path from reactants to intermediate",
    "Substitution path: Black curve continuing from intermediate, over a second peak, down to substitution products",
    "Substitution product: Bromobenzene structure + HBr (magenta) with 'Substitution' text",
    "Dashed horizontal reference line for substitution products (lower than reactants)",
    "Addition path: Magenta curve branching from intermediate, over a different second peak, ending at addition products",
    "Addition product: 1,2-dibromocyclohexadiene structure in brackets, with 'Addition (does not occur)' text in magenta",
    "Dashed horizontal reference line for addition products (higher than reactants)",
    "Vertical double-headed arrow labeled ΔG‡ between reactant level and first peak",
    "Vertical double-headed arrow labeled ΔG° between reactant level and substitution product level"
  ],
  "interactions": [
    {
      "id": "reactionPhase",
      "type": "button",
      "label": "Step through reaction",
      "states": [
        "Reactants",
        "First Transition State",
        "Intermediate",
        "Second Transition State",
        "Products"
      ],
      "default": "Reactants",
      "teaches": "The reaction proceeds in two steps: breaking aromaticity to form a high-energy intermediate, then resolving into a final product."
    },
    {
      "id": "pathwayToggle",
      "type": "toggle",
      "label": "Reaction Pathway",
      "options": [
        "Substitution",
        "Addition"
      ],
      "default": "Substitution",
      "teaches": "The substitution pathway ends at a lower energy level than the reactants (downhill), while the addition pathway ends at a higher energy level (uphill)."
    },
    {
      "id": "energyArrows",
      "type": "click",
      "teaches": "Clicking ΔG‡ highlights the activation energy barrier determining reaction rate, while clicking ΔG° highlights the overall thermodynamic energy difference determining product stability."
