function drawBenzeneRing(group, cx, cy, r = 25) {
    const pts = [];
    for (let i = 0; i < 6; i++) {
        pts.push([cx + r * Math.sin(i * Math.PI / 3), cy - r * Math.cos(i * Math.PI / 3)]);
    }
    group.polygon(pts.map(p => p.join(',')).join(' ')).fill('none').stroke({ width: 1.5, color: '#000', linejoin: 'round' });
    return pts;
}

function drawInternalBonds(group, cx, cy, r, indices) {
    for (let i of indices) {
        const p1 = [cx + 0.72 * r * Math.sin(i * Math.PI / 3 + 0.2), cy - 0.72 * r * Math.cos(i * Math.PI / 3 + 0.2)];
        const p2 = [cx + 0.72 * r * Math.sin((i + 1) * Math.PI / 3 - 0.2), cy - 0.72 * r * Math.cos((i + 1) * Math.PI / 3 - 0.2)];
