    group.text('Br').move(p1[0] + 24, p1[1] - 16).font({ size: 14, family: 'sans-serif' }).fill('#e6007e');
    group.line(p1[0], p1[1], p1[0] + 15, p1[1] + 15).stroke({ width: 1, color: '#000' });
    group.text('H').move(p1[0] + 18, p1[1] + 12).font({ size: 13, family: 'sans-serif' });

