      "state": {
        "reactionPhase": "Intermediate",
        "pathwayToggle": "Substitution"
      }
    },
    {
      "title": "The Substitution Pathway",
      "narration": "In substitution, a proton is lost to restore the stable aromatic ring. The final energy drops well below the starting level, making it thermodynamically favorable.",
      "state": {
        "reactionPhase": "Products",
        "pathwayToggle": "Substitution"
      }
    },
    {
      "title": "The Addition Pathway",
