// @FIGURE_CODE_BEGIN
const W = 800;
const H = 600;
const draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, W, H);

// Background
draw.rect(W + 200, H + 200).move(-100, -100).fill('#eaf4fa');

// Setup reusable stroke styles
const dashOpt = { width: 1.5, color: '#666', dasharray: '6,4' };
const magentaDash = { width: 1.5, color: '#e6007e', dasharray: '6,4' };

// ── AXES ────────────────────────────────────────────────────────────

// Y-axis: Energy (Arrow with gradient)
const yGrad = draw.gradient('linear', function (add) {
    add.stop(0, '#ff7f50'); // Orange at top
    add.stop(1, '#fffacd'); // Pale yellow at bottom
}).from(0, 0).to(0, 1);

draw.path('M 40 540 L 40 50 L 30 50 L 50 25 L 70 50 L 60 50 L 60 540 Z')
    .fill(yGrad).stroke({ width: 1, color: '#000', linejoin: 'round' });

draw.text('Energy')
    .move(15, 300)
    .font({ size: 16, weight: 'bold', family: 'sans-serif' })
    .transform({ rotate: -90, cx: 15, cy: 300 });

// X-axis: Reaction Progress
draw.line(80, 565, 740, 565).stroke({ width: 2, color: '#e6007e' });
draw.polygon('735,560 735,570 750,565').fill('#e6007e');
draw.text('Reaction progress')
    .font({ size: 16, family: 'sans-serif' })
    .cx(410).y(575);


// ── ENERGY REFERENCE LINES ──────────────────────────────────────────

// Reactants reference line
draw.line(100, 330, 480, 330).stroke(dashOpt);
// TS1 reference line
draw.line(280, 80, 350, 80).stroke(dashOpt);
// Intermediate reference line
draw.line(390, 180, 470, 180).stroke(dashOpt);


// ── PATHWAYS & GROUPS ───────────────────────────────────────────────

// Reactants to Intermediate common curve
const commonCurve = draw.path("M 200 330 C 240 330, 260 80, 310 80 C 360 80, 380 180, 420 180")
    .fill('none').stroke({ width: 3, color: '#111', linecap: 'round' });

const subGrp = draw.group();
const addGrp = draw.group();

// Substitution Curve & Elements
// Note: TS2 Substitution peak is at y=110 (higher energy than TS2 addition peak)
subGrp.path("M 420 180 C 450 180, 470 110, 510 110 C 550 110, 580 450, 630 450")
    .fill('none').stroke({ width: 3, color: '#111', linecap: 'round' });
subGrp.line(430, 450, 700, 450).stroke(dashOpt); // Sub product reference line

// Addition Curve & Elements
// Note: TS2 Addition peak is at y=130 (slightly lower energy than substitution peak)
addGrp.path("M 420 180 C 470 180, 490 130, 530 130 C 570 130, 590 260, 650 260")
    .fill('none').stroke({ width: 3, color: '#e6007e', linecap: 'round' });
addGrp.line(430, 260, 720, 260).stroke(magentaDash); // Add product reference line


// ── MOLECULE DRAWING HELPER FUNCTIONS ───────────────────────────────

function drawBenzeneRing(group, cx, cy, r = 25) {
    const pts = [];
    for (let i = 0; i < 6; i++) {
        pts.push([cx + r * Math.sin(i * Math.PI / 3), cy - r * Math.cos(i * Math.PI / 3)]);
    }
    group.polygon(pts.map(p => p.join(',')).join(' ')).fill('none').stroke({ width: 1.5, color: '#000', linejoin: 'round' });
    return pts;
}

function drawInternalBonds(group, cx, cy, r, indices) {
    const offset = 6;
    const shrink = 3.5;
    for (let i of indices) {
        const a1 = i * Math.PI / 3;
        const a2 = (i + 1) * Math.PI / 3;
        const p1x = cx + r * Math.sin(a1);
        const p1y = cy - r * Math.cos(a1);
        const p2x = cx + r * Math.sin(a2);
        const p2y = cy - r * Math.cos(a2);

        const dx = p2x - p1x;
        const dy = p2y - p1y;
        const len = Math.sqrt(dx * dx + dy * dy);

        let nx = -dy / len;
        let ny = dx / len;

        const vcx = cx - p1x;
        const vcy = cy - p1y;
        const sign = (nx * vcx + ny * vcy) > 0 ? 1 : -1;

        const ux = dx / len;
        const uy = dy / len;

        const ix1 = p1x + sign * nx * offset + ux * shrink;
        const iy1 = p1y + sign * ny * offset + uy * shrink;
        const ix2 = p2x + sign * nx * offset - ux * shrink;
        const iy2 = p2y + sign * ny * offset - uy * shrink;

        group.line(ix1, iy1, ix2, iy2).stroke({ width: 1.5, color: '#000', linecap: 'round' });
    }
}

function drawBenzene(group, cx, cy) {
    drawBenzeneRing(group, cx, cy);
    drawInternalBonds(group, cx, cy, 25, [0, 2, 4]);
}

function drawArenium(group, cx, cy) {
    const pts = drawBenzeneRing(group, cx, cy);

    // Delocalized charge arc sitting cleanly inside without touching the single bonds
    const arcR = 17; 
    const aStart = Math.PI / 3 + 0.4;
    const aEnd = Math.PI / 3 - 0.4;
    const pStart = [cx + arcR * Math.sin(aStart), cy - arcR * Math.cos(aStart)];
    const pEnd = [cx + arcR * Math.sin(aEnd), cy - arcR * Math.cos(aEnd)];

    group.path(`M ${pStart[0]} ${pStart[1]} A ${arcR} ${arcR} 0 1 1 ${pEnd[0]} ${pEnd[1]}`)
         .fill('none').stroke({ width: 1.5, color: '#000', dasharray: '4,3' });

    group.text('+').font({ size: 16, weight: 'bold' }).fill('#000').cx(cx).y(cy - 9);

    const p1 = pts[1]; // top right sp3 carbon
    group.line(p1[0], p1[1], p1[0] + 10, p1[1] - 16).stroke({ width: 1, color: '#000' });
    group.text('H').font({ size: 13, family: 'sans-serif' }).cx(p1[0] + 14).y(p1[1] - 32);

    group.line(p1[0], p1[1], p1[0] + 16, p1[1] + 6).stroke({ width: 1, color: '#000' });
    group.text('Br').font({ size: 14, family: 'sans-serif' }).fill('#e6007e').cx(p1[0] + 26).y(p1[1] - 4);
}

function drawBromobenzene(group, cx, cy) {
    const pts = drawBenzeneRing(group, cx, cy);
    drawInternalBonds(group, cx, cy, 25, [0, 2, 4]);

    const p1 = pts[1]; // top right carbon
    group.line(p1[0], p1[1], p1[0] + 15, p1[1] - 10).stroke({ width: 1, color: '#000' });
    group.text('Br').font({ size: 14, family: 'sans-serif' }).fill('#e6007e').cx(p1[0] + 26).y(p1[1] - 22);
}

function drawAdditionProduct(group, cx, cy) {
    const pts = drawBenzeneRing(group, cx, cy);
    drawInternalBonds(group, cx, cy, 25, [2, 4]);

    // H and Br at 0 (top)
    const p0 = pts[0];
    group.line(p0[0], p0[1], p0[0] - 15, p0[1] - 15).stroke({ width: 1, color: '#000' });
    group.text('H').font({ size: 13, family: 'sans-serif' }).cx(p0[0] - 20).y(p0[1] - 32);
    group.line(p0[0], p0[1], p0[0] + 15, p0[1] - 15).stroke({ width: 1, color: '#000' });
    group.text('Br').font({ size: 14, family: 'sans-serif' }).fill('#e6007e').cx(p0[0] + 20).y(p0[1] - 32);

    // H and Br at 1 (top right)
    const p1 = pts[1];
    group.line(p1[0], p1[1], p1[0] + 20, p1[1] - 5).stroke({ width: 1, color: '#000' });
    group.text('Br').font({ size: 14, family: 'sans-serif' }).fill('#e6007e').cx(p1[0] + 30).y(p1[1] - 14);
    group.line(p1[0], p1[1], p1[0] + 15, p1[1] + 15).stroke({ width: 1, color: '#000' });
    group.text('H').font({ size: 13, family: 'sans-serif' }).cx(p1[0] + 20).y(p1[1] + 12);

    // Brackets
    group.path(`M ${cx - 45} ${cy - 45} L ${cx - 55} ${cy - 45} L ${cx - 55} ${cy + 45} L ${cx - 45} ${cy + 45}`)
         .fill('none').stroke({ width: 1.5, color: '#000' });
    group.path(`M ${cx + 50} ${cy - 45} L ${cx + 60} ${cy - 45} L ${cx + 60} ${cy + 45} L ${cx + 50} ${cy + 45}`)
         .fill('none').stroke({ width: 1.5, color: '#000' });
}


// ── DRAW MOLECULES & LABELS ─────────────────────────────────────────

// 1. Reactants
const reactantsGrp = draw.group();
drawBenzene(reactantsGrp, 110, 390);
reactantsGrp.text('+').font({ size: 18, family: 'sans-serif' }).fill('#000').cx(150).y(380);
reactantsGrp.text('Br').font({ size: 18, family: 'sans-serif' }).fill('#e6007e').cx(175).y(380);
reactantsGrp.text('2').font({ size: 12, family: 'sans-serif' }).fill('#e6007e').cx(190).y(388);

reactantsGrp.rect(130, 80).move(80, 350).fill('transparent').css('cursor', 'pointer')
    .on('click', () => showPopup('Reactants', 'Benzene is highly stable due to its fully delocalized aromatic ring. Breaking this aromaticity requires a massive energy input.'))
    .on('mousemove', e => showTooltip('Benzene + Bromine', e)).on('mouseleave', hideTooltip);


// 2. Intermediate
const intermediateGrp = draw.group();
drawArenium(intermediateGrp, 420, 260);

intermediateGrp.rect(100, 100).move(370, 210).fill('transparent').css('cursor', 'pointer')
    .on('click', () => showPopup('Arenium Ion Intermediate', 'The aromatic ring is temporarily broken by the addition of the electrophile. This cationic species is highly unstable and reactive.'))
    .on('mousemove', e => showTooltip('Carbocation Intermediate', e)).on('mouseleave', hideTooltip);


// 3. Substitution Product
drawBromobenzene(subGrp, 590, 500);
subGrp.text(add => {
    add.tspan('+ H').fill('#000');
    add.tspan('Br').fill('#e6007e');
}).font({ size: 16, family: 'sans-serif' }).cx(650).y(485);

subGrp.text('Substitution').font({ size: 16, family: 'sans-serif' }).fill('#000').cx(590).y(545);

subGrp.rect(150, 120).move(520, 440).fill('transparent').css('cursor', 'pointer')
    .on('click', () => showPopup('Substitution Product', 'Loss of a proton restores the stable aromatic ring. Because aromaticity is recovered, the final energy state drops well below the starting reactants, making it thermodynamically favorable.'))
    .on('mousemove', e => showTooltip('Bromobenzene + HBr', e)).on('mouseleave', hideTooltip);


// 4. Addition Product
drawAdditionProduct(addGrp, 670, 170);
addGrp.text('Addition').font({ size: 16, family: 'sans-serif' }).fill('#e6007e').cx(670).y(230);
addGrp.text('(does not occur)').font({ size: 14, family: 'sans-serif', weight: 'bold' }).fill('#e6007e').cx(670).y(248);

addGrp.rect(140, 140).move(600, 110).fill('transparent').css('cursor', 'pointer')
    .on('click', () => showPopup('Addition Product', 'If a second bromide added, the aromatic ring would remain broken permanently. The product rests at a higher energy state than the starting materials, so this reaction does not occur.'))
    .on('mousemove', e => showTooltip('1,2-dibromocyclohexadiene', e)).on('mouseleave', hideTooltip);


// ── ENERGY ARROWS (ΔG) ──────────────────────────────────────────────

const markerEndG = draw.marker(10, 10, function (add) {
    add.polygon('0,0 10,5 0,10').fill('#000');
}).ref(10, 5);
const markerStartG = draw.marker(10, 10, function (add) {
    add.polygon('10,0 0,5 10,10').fill('#000');
}).ref(0, 5);

// Activation Energy Arrow (ΔG‡)
draw.line(290, 85, 290, 325).stroke({ width: 1.5, color: '#000' })
    .marker('start', markerStartG).marker('end', markerEndG);
draw.text('ΔG‡').font({ size: 16, family: 'sans-serif' }).cx(265).y(195);

draw.rect(60, 250).move(245, 80).fill('transparent').css('cursor', 'pointer')
    .on('click', () => showPopup('Activation Energy (ΔG‡)', 'The immense energy required to reach the first transition state and break aromaticity. This barrier determines the sluggish rate of the reaction.'))
    .on('mousemove', e => showTooltip('Activation Energy Barrier', e)).on('mouseleave', hideTooltip);

// Overall Free Energy Arrow (ΔG°)
draw.line(470, 335, 470, 445).stroke({ width: 1.5, color: '#000' })
    .marker('start', markerStartG).marker('end', markerEndG);
draw.rect(40, 24).center(505, 390).fill('#eaf4fa'); // background for readability
draw.text('ΔG°').font({ size: 16, family: 'sans-serif' }).cx(505).y(380);

draw.rect(60, 120).move(450, 330).fill('transparent').css('cursor', 'pointer')
    .on('click', () => showPopup('Thermodynamic Energy Difference (ΔG°)', 'The overall energy change from reactants to products. A negative ΔG° (downhill curve) dictates that the substitution products are thermodynamically favored.'))
    .on('mousemove', e => showTooltip('Overall Energy Change', e)).on('mouseleave', hideTooltip);


// ── REACTION PROGRESS INDICATOR (THE DOT) ───────────────────────────

const rxnDot = draw.circle(16).fill('#fff').stroke({ width: 4, color: '#ff7f50' }).center(200, 330);
rxnDot.css('pointer-events', 'none');


// ── INTERACTIVITY & DEMO STEPS LOGIC ────────────────────────────────

let currentPhase = "Reactants";
let currentPathway = "Substitution";

window.updateReactionPhase = function (val) {
    currentPhase = val;
    moveDot();
};

window.updatePathwayToggle = function (val) {
    currentPathway = val;
    moveDot();
};

window.manualUpdate = function () {
    const phase = document.getElementById('reactionPhaseInput').value;
    const pathway = document.getElementById('pathwayToggleInput').value;
    window.updateReactionPhase(phase);
    window.updatePathwayToggle(pathway);
};

function moveDot() {
    let x = 200, y = 330;
    if (currentPhase === "Reactants") { x = 200; y = 330; }
    else if (currentPhase === "First Transition State") { x = 310; y = 80; }
    else if (currentPhase === "Intermediate") { x = 420; y = 180; }
    else if (currentPhase === "Second Transition State") {
        x = (currentPathway === 'Substitution') ? 510 : 530;
        y = (currentPathway === 'Substitution') ? 110 : 130;
    }
    else if (currentPhase === "Products") {
        x = (currentPathway === 'Substitution') ? 630 : 650;
        y = (currentPathway === 'Substitution') ? 450 : 260;
    }
    rxnDot.animate(450, '<>').center(x, y);
}

// Hover effects for the pathways
subGrp.on('mousemove', e => showTooltip('Substitution Pathway (Thermodynamically favorable)', e)).on('mouseleave', hideTooltip);
addGrp.on('mousemove', e => showTooltip('Addition Pathway (Thermodynamically unfavorable)', e)).on('mouseleave', hideTooltip);


const demoSteps = [
    {
        title: "Starting the Reaction",
        narration: "The reaction begins with stable, aromatic benzene and bromine. To react, they must overcome a massive activation energy barrier (ΔG‡).",
        state: { reactionPhase: "Reactants", pathwayToggle: "Substitution" }
    },
    {
        title: "The Cationic Intermediate",
        narration: "Overcoming the first barrier forms a high-energy cationic intermediate, temporarily breaking the stable aromatic ring.",
        state: { reactionPhase: "Intermediate", pathwayToggle: "Substitution" }
    },
    {
        title: "The Substitution Pathway",
        narration: "In substitution, a proton is lost to restore the stable aromatic ring. The final energy drops well below the starting level, making it thermodynamically favorable.",
        state: { reactionPhase: "Products", pathwayToggle: "Substitution" }
    },
    {
        title: "The Addition Pathway",
        narration: "If a second bromine added instead, the aromatic ring would remain broken. This pathway ends at a higher energy level than it started, which is why it does not occur.",
        state: { reactionPhase: "Products", pathwayToggle: "Addition" }
    }
];

let currentStep = 0;

function applyState(state) {
    document.getElementById('reactionPhaseInput').value = state.reactionPhase;
    document.getElementById('pathwayToggleInput').value = state.pathwayToggle;
    window.updateReactionPhase(state.reactionPhase);
    window.updatePathwayToggle(state.pathwayToggle);
}

window.nextStep = function () {
    if (currentStep < demoSteps.length - 1) {
        currentStep++;
        renderStep();
    }
}
window.prevStep = function () {
    if (currentStep > 0) {
        currentStep--;
        renderStep();
    }
}

function renderStep() {
    const step = demoSteps[currentStep];
    document.getElementById('demoTitle').textContent = step.title;
    document.getElementById('demoNarration').textContent = step.narration;
    document.getElementById('stepLabel').textContent = `Step ${currentStep + 1} of ${demoSteps.length}`;

    document.getElementById('btnPrev').disabled = (currentStep === 0);
    document.getElementById('btnNext').disabled = (currentStep === demoSteps.length - 1);

    document.getElementById('btnPrev').style.opacity = (currentStep === 0) ? "0.4" : "1";
    document.getElementById('btnNext').style.opacity = (currentStep === demoSteps.length - 1) ? "0.4" : "1";

    applyState(step.state);
}

// Initialize
setTimeout(renderStep, 100);
window.__markRendered();
// @FIGURE_CODE_END

